 "content": "def transform(grid):
    # Find the dominant background, then extend a foreground run to the right
    # by changing the trailing background cells to color 1.
    from collections import Counter
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        occupied = [c for c, value in enumerate(row) if value != background]
